#!/usr/bin/python3
"""New external implementation. No producer code is imported or executed.
Complete multiplicatively factored rough fibres; Acb entire quadrature.
"""
import hashlib,json,math,time
from pathlib import Path
from fractions import Fraction as Q
from flint import arb,acb,ctx
ctx.prec=384
ctx.threads=1
C=690988; H=2299999; X=6000000185827; W=66476100549959
A=arb(4)/25; B=arb(3)/16; DELTA=arb(1)/10
F=Path('frozen')
checks=0

def gate(ok,msg):
    global checks
    checks+=1
    if not ok: raise AssertionError(msg)

def rat(x): return Q(str(x))
def ends(v): return rat(v.lower().fmpq()),rat(v.upper().fmpq())
def dec(q,d,up=False):
    q=Q(q); z=q*10**d
    k=-((-z.numerator)//z.denominator) if up else z.numerator//z.denominator
    sg='-' if k<0 else ''; k=abs(k)
    return sg+str(k//10**d)+'.'+str(k%10**d).zfill(d)
def floor_trunc(q,d): return dec(q,d)
def ceil_trunc(q,d): return dec(q,d,True)
def rec(v,d=12):
    lo,hi=ends(v)
    return {'lo':str(lo),'hi':str(hi),'FLOOR'+str(d):floor_trunc(lo,d),'CEIL'+str(d):ceil_trunc(hi,d)}
def cell(v,bits):
    w=v*(1<<bits)
    lo=int(w.lower().floor().fmpz());hi=int(w.upper().ceil().fmpz())
    gate(hi-lo in (0,1),'ambiguous dyadic cell')
    return lo,hi

def compare(v,old,name,contain=True):
    lo,hi=ends(v); a,b=Q(old['lo']),Q(old['hi'])
    if contain:
        gate(a<=lo and hi<=b, 'not contained: '+name)
    else: gate(lo<=b and a<=hi,'no overlap: '+name)
    for k,val in old.items():
        if k.lower().startswith('floor'):
            d=int(k[5:]);gate(dec(a,d)==val,'old FLOOR wrong: '+name)
        if k.lower().startswith('ceil'):
            d=int(k[4:]);gate(dec(b,d,True)==val,'old CEIL wrong: '+name)

for q,d,lo,hi in [('123/1000',2,'0.12','0.13'),('-123/1000',2,'-0.13','-0.12'),('-1/1000',2,'-0.01','0.00'),('1/10',2,'0.10','0.10')]:
    gate(floor_trunc(Q(q),d)==lo and ceil_trunc(Q(q),d)==hi,'rounding selftest')

def drift(x):
    # Algebraically separate the logarithms, instead of producer sqrt/log.
    return (1+x*x).log()/8-(4*arb.pi()).log()/4-1/(2*(1+x*x))
c0=drift(arb(X))
def coefficient(logn,t): return ((t*logn/4-arb(1)/2-t*c0)*logn).exp()
def wall(j,t): return 4*arb.pi()*(j*j-t/16)

# Unique four nested prime-power factors, sorted only after enumeration.
smooth=[]
def powers(prefix,parity,j):
    if j==4:
        smooth.append((prefix,parity));return
    p=(2,3,5,7)[j]; n=prefix;sg=parity
    while n<=C:
        powers(n,sg,j+1);n*=p;sg=-sg
powers(1,1,0);smooth.sort()
gate(len(smooth)==len(set(s for s,_ in smooth)),'smooth duplicates')
logs={s:arb(s).log() for s,_ in smooth}
smdata=[(s,sign,logs[s],coefficient(logs[s],A)) for s,sign in smooth]
raw=[None]*(C+1);weights={};bins={}
raw_count=0; coreplus=coreminus=None; aligned_total=arb(0);aligned_core=arb(0)
t0=time.monotonic()
for r in range(1,C+1):
    if math.gcd(r,210)!=1:continue
    lr=arb(r).log(); ar=coefficient(lr,A); alr=coefficient(lr,arb(13)/80)
    fp=arb(0);fm=arb(0)
    for s,sg,ls,as_ in smdata:
        n=r*s
        if n>C:break
        # a_(rs)=a_r a_s exp(t log(r)log(s)/2), different analytic evaluation.
        v=ar*as_*(A*lr*ls/2).exp()
        gate(raw[n] is None,'duplicate raw product')
        raw[n]=cell(v,56);raw_count+=1; fp+=v;fm+=sg*v
        # Distinct accepted745 anchor through the SAME factorization path.
        vs=coefficient(ls,arb(13)/80)
        va=alr*vs*((arb(13)/80)*lr*ls/2).exp()
        aligned_total+=va
        if r==1:aligned_core+=va
    if r==1:
        coreplus=fp;coreminus=fm
        gate(fp>0 and fm>0,'source denominators')
        weights[0]=((8*(DELTA/fp)**2+(DELTA/fm)**2)/9).sqrt()
    else:
        v=((8*(fp/coreplus)**2+(fm/coreminus)**2)/9).sqrt()
        gate(v>0,'weight nonpositive');weights[r]=v
        e=r.bit_length()-1;g=16*e+(16*r//(1<<e)-16)
        if g not in bins:bins[g]=[r,r,0,0,arb(0)]
        z=bins[g];z[0]=min(z[0],r);z[1]=max(z[1],r);z[2]+=1;z[3]+=r;z[4]+=v
    if r%100001==0:print('HEARTBEAT rough',r,flush=True)
gate(raw_count==C and all(v is not None for v in raw[1:]),'incomplete raw census')
gate(len(weights)==157940 and len(bins)==224,'complete weight/bin census')
gate(sum(z[2] for z in bins.values())==len(weights)-1,'rough count')
gate(sum(z[3] for z in bins.values())==sum(r for r in range(2,C+1) if math.gcd(r,210)==1),'rough sum')
# Incremental byte comparison avoids shipping either large table.
hr=hashlib.sha256();hw=hashlib.sha256()
for n in range(1,C+1):hr.update(('%d %d %d\n'%(n,*raw[n])).encode())
for r,v in sorted(weights.items()):hw.update(('%d %d %d\n'%(r,*cell(v,56))).encode())
orig=json.loads(Path('INPUT_ORIGINS.json').read_text())
gate(hr.hexdigest()==orig['complete_raw_digest'],'complete raw digest')
gate(hw.hexdigest()==orig['complete_weight_digest'],'complete weight digest')
binrows=[(-1,0,0,0,0,*cell(weights[0],100))]
for g,z in sorted(bins.items()):binrows.append((g,*z[:4],*cell(z[4],100)))
bintext=''.join(' '.join(map(str,z))+'\n' for z in binrows)
for name in ['m774_p_bins.txt','m774_s_bins.txt']:
    gate(bintext==(F/name).read_text(),'complete bin stream '+name)
Path('OWN_BINS.txt').write_text(bintext)
anchor745=json.loads((F/'m745_DIMENSION_PRIMARY.json').read_text())
compare(aligned_total,anchor745['total'],'745 total')
a4=next(z for z in anchor745['records'] if z['k']==4)
for name,v in [('core',aligned_core),('rough',aligned_total-aligned_core),('sufficient_floor',2*aligned_core-aligned_total)]:compare(v,a4[name],'745 '+name)
summary={'raw_cells':C,'weight_cells':len(weights),'positive_bins':len(bins),'synthetic_bins':1,'smooth_terms':len(smooth),'raw_sha256':hr.hexdigest(),'weight_sha256':hw.hexdigest(),'bin_sha256':hashlib.sha256(bintext.encode()).hexdigest(),'coreplus':rec(coreplus),'coreminus':rec(coreminus),'vstar':rec(weights[0]),'sum_v':rec(sum(weights.values(),arb(0))),'anchor745':rec(2*aligned_core-aligned_total)}
# Compare independently regenerated directed source summaries.
for line in (F/'m774_p_summary.txt').read_text().splitlines():
    name,lo,hi=line.split()
    v={'anchor745':2*aligned_core-aligned_total,'core_plus':coreplus,'core_minus':coreminus,'weight_sum':sum(weights.values(),arb(0)),'synthetic_v':weights[0]}[name]
    l,u=ends(v*10**12)
    gate(int(lo)==l.numerator//l.denominator and int(hi)==-((-u.numerator)//u.denominator),'source summary '+name)
print('COMPLETE_COEFFICIENTS_PASS',C,len(weights),len(bins),flush=True)

# Entire Acb integrand: no branch-cut risk even on complex quadrature balls.
def integral(x,U):
    if U==C:return arb(0)
    l=arb(C).log();h=arb(U).log()-l;aa=A/4;bb=arb(1)/2-A*drift(x)
    def f(z,analytic):
        y=l+h*z
        return h*(aa*y*y+bb*y).exp()
    out=acb.integral(f,0,1,rel_tol=arb(2)**-330,abs_tol=arb(2)**-330)
    gate(out.is_finite() and out.imag.contains(0),'quadrature finite-real')
    return out.real

def recover(s):
    gate(s>=0,'inward recovery')
    if s.is_zero():return DELTA
    mass=arb(0)
    for z in bins.values():
        mass+=z[4]*(-(-2*s*arb(z[0]).log()).expm1())
    return DELTA*(1+mass/weights[0]).sqrt()

def evaluate(L,U):
    gate(C<=L<=U<=H,'index domain')
    x=arb(X) if L==C else wall(L,B)
    s=arb(0) if L==C else A*(drift(x)-c0)
    entry=integral(x,U); norm=recover(s)
    return {'L':L,'U':U,'x_left':x,'s':s,'old_norm_lower_expression':norm,'entry_integral_upper':entry,'retained_lower_expression':norm-entry,'entry_log_slope':-arb(1)/2+A*(arb(U).log()/2-drift(x)),'heat_support_gap':4*drift(x)-arb(U).log()}

P=json.loads((F/'m774_PRIMARY_RESULT.json').read_text());S=json.loads((F/'m774_SECONDARY_RESULT.json').read_text())
cache={};records=[];compared=0
for category in ['leaves','point_controls','rejected_parents']:
    for old in P[category]:
        L,U=old['L'],old['U'];key=(L,U)
        if key not in cache:cache[key]=evaluate(L,U)
        z=cache[key]
        gate(z['entry_log_slope']<0,'decreasing density')
        gate(z['heat_support_gap']>0,'actual support heat')
        for name,v in old.items():
            if isinstance(v,dict) and 'lo' in v:
                compare(z[name],v,category+' '+str(key)+' '+name);compared+=1
        if category!='rejected_parents':
            ss=next(v for v in S[category] if (v['L'],v['U'])==key)
            for name,v in ss.items():
                if isinstance(v,dict) and 'lo' in v and name in z:
                    compare(z[name],v,'second '+category+' '+str(key)+' '+name);compared+=1
        if category=='leaves':gate(z['retained_lower_expression']>arb(1)/100,'leaf fails')
        if category=='rejected_parents':gate(z['retained_lower_expression']<arb(1)/100,'parent classification')
        records.append({'category':category,**{k:rec(v) if isinstance(v,arb) else v for k,v in z.items()}})

anchors={'c_source':c0,'entry100000':100000*coefficient(arb(C).log(),A),'support_gap790988':4*c0-arb(790988).log(),'source_left_gap':arb(X)-wall(C,A),'source_right_gap':wall(C+1,B)-X,'far_left_gap':arb(W)-wall(H,A),'far_right_gap':wall(H+1,B)-W}
for k,v in anchors.items():
    compare(v,P['anchors'][k],'anchor primary '+k);compare(v,S['anchors'][k],'anchor secondary '+k)
# Source767 anchor products retain both accepted scalar representations.
old767=json.loads((F/'m767_COMPOSITION_RESULT.json').read_text())['scalars']
for oldname,newname in [('c','c_source'),('entry','entry100000'),('support_gap','support_gap790988'),('source_left_gap','source_left_gap'),('source_right_gap','source_right_gap')]:
    for mode in ['arb','rational_series']:
        lo,hi=old767[oldname][mode];compare(anchors[newname],{'lo':lo,'hi':hi},'767 '+oldname+' '+mode)
# Far seam is separately pinned to729 through774's accepted anchor fields.
old729=json.loads((F/'m729_primary_results.json').read_text())['intervals']
for key,name in [('TAIL_SEAM_LOWER_GAP','far_left_gap'),('TAIL_SEAM_UPPER_GAP','far_right_gap')]:
    lo,hi=old729[key];compare(anchors[name],{'lo':lo,'hi':hi},'729 '+key)
for name in ['source_left_gap','source_right_gap','far_left_gap','far_right_gap']:gate(anchors[name]>0,name)
leaves=[cache[(z['L'],z['U'])] for z in P['leaves']]
minimum=min(leaves,key=lambda z:ends(z['retained_lower_expression'])[0])
for z in leaves:
    if z is not minimum:gate(minimum['retained_lower_expression']<z['retained_lower_expression'],'unique sufficient minimum')
gate((minimum['L'],minimum['U'])==(1897746,2098872),'minimum location')
out={'status':'PRIMARY_EXTERNAL_COMPLETE_PASS','arithmetic':'own Arb384 multiplicative coefficients; entire Acb quadrature','complete':summary,'scalar_comparisons':compared,'rows':records,'anchors':{k:rec(v,18) for k,v in anchors.items()},'minimum':{'L':minimum['L'],'U':minimum['U'],**rec(minimum['retained_lower_expression'])},'checks':checks}
Path('PRIMARY_AUDIT.json').write_text(json.dumps(out,indent=2,sort_keys=True)+'\n')
print('MINIMUM',out['minimum']['L'],out['minimum']['U'],'FLOOR12',out['minimum']['FLOOR12'],'CEIL12',out['minimum']['CEIL12'])
print('PRIMARY_EXTERNAL_COMPLETE_PASS checks',checks,'scalar_fields',compared,flush=True)

