#!/usr/bin/python3
"""External line two: mpmath real intervals, exact Machin pi, symmetric double
power series with its whole analytic tail. No primary/producer imports.
"""
from fractions import Fraction as Q
import json,math,hashlib,bisect
from pathlib import Path
from mpmath import iv
iv.dps=110
C=690988;H=2299999;X=6000000185827;W=66476100549959
F=Path('frozen'); checks=0

def need(p,s):
 global checks
 checks+=1
 if not p:raise AssertionError(s)
def iq(x):
 x=Q(x);return iv.mpf(x.numerator)/x.denominator
def endpoints(x):
 def f(t):
  sign,man,e,bc=t
  return Q((-1 if sign else 1)*man)*(Q(2)**e)
 return f(x._mpi_[0]),f(x._mpi_[1])
def enclosure(lo,hi):return iv.mpf([iq(lo).a,iq(hi).b])
def trunc(q,d,ceil=False):
 n=(Q(q)*10**d);k=n.numerator//n.denominator
 if ceil and n!=k:k+=1
 return ('-' if k<0 else '')+str(abs(k)//10**d)+'.'+str(abs(k)%10**d).zfill(d)
def save(x,d=12):
 a,b=endpoints(x);return {'lo':str(a),'hi':str(b),'FLOOR'+str(d):trunc(a,d),'CEIL'+str(d):trunc(b,d,True)}
def pos(x):return endpoints(x)[0]>0
def neg(x):return endpoints(x)[1]<0
for q,d,l,h in [(Q(-123,1000),2,'-0.13','-0.12'),(Q(123,1000),2,'0.12','0.13'),(Q(-1,1000),2,'-0.01','0.00'),(Q(1,10),2,'0.10','0.10')]:need(trunc(q,d)==l and trunc(q,d,True)==h,'secondary rounding')

def arctan_bracket(k,n=126):
 # Alternating remainder exactly between partial sum and next partial sum.
 s=sum((Q((-1)**j,(2*j+1)*k**(2*j+1)) for j in range(n)),Q(0))
 z=s+Q((-1)**n,(2*n+1)*k**(2*n+1))
 return min(s,z),max(s,z)
a,b=arctan_bracket(5);c,d=arctan_bracket(239)
PI=enclosure(16*a-4*d,16*b-4*c)
need(pos(PI-iq(3)) and pos(iq(22)/7-PI),'Machin bounds')
a=iq('4/25');b=iq('3/16');delta=iq('1/10')
def cfun(x):
 return iv.log(iv.sqrt(1+x*x)/(4*PI))/4-1/(2*(1+x*x))
c0=cfun(iq(X))
def wall(j,t):return 4*PI*(j*j-t/16)

# Independent exact support census: wheel residues, sorted dyadic rational
# boundaries and bisection, not the primary's gcd/bit_length partition.
res=[r for r in range(1,210) if math.gcd(r,210)==1]
need(len(res)==48,'Euler wheel')
edges=[(Q((16+k)*2**e,16),16*e+k) for e in range(20) for k in range(16)]
edge_values=[x for x,_ in edges];metadata={};rough_count=0;rough_sum=0
for base in range(0,C+1,210):
 for v in res:
  r=base+v
  if r<=1 or r>C:continue
  g=edges[bisect.bisect_right(edge_values,r)-1][1]
  if g not in metadata:metadata[g]=[r,r,0,0]
  z=metadata[g];z[0]=min(z[0],r);z[1]=max(z[1],r);z[2]+=1;z[3]+=r
  rough_count+=1;rough_sum+=r
bins=[];star=None
for line in (F/'m774_s_bins.txt').read_text().splitlines():
 g,lo,hi,count,total,bl,bh=map(int,line.split())
 val=enclosure(Q(bl,2**100),Q(bh,2**100))
 if g==-1:
  need((lo,hi,count,total)==(0,0,0,0),'synthetic metadata');star=val
 else:
  need(metadata.pop(g)==[lo,hi,count,total],'complete independent bin geometry')
  bins.append((lo,hi,val))
need(not metadata and len(bins)==224 and rough_count==157939 and star is not None,'bin support complete')

# Symmetric double series. All omitted terms, not a numerical quadrature
# tolerance, are bounded. The bounds |P|<1 and 0<=Q<1 are checked on each row.
K=64
TAIL=iq(9)*(iq(1)/math.factorial(2*K+2)+iq(1)/math.factorial(K+1))
def entrant_integral(x,U):
 if U==C:return iq(0),iq(0)
 l=iv.log(iq(C));u=iv.log(iq(U));m=(l+u)/2;h=(u-l)/2
 aa=a/4;bb=iq(1)/2-a*cfun(x)
 e=aa*m*m+bb*m;p=(2*aa*m+bb)*h;q=aa*h*h
 plo,phi=endpoints(p);qlo,qhi=endpoints(q)
 need(-1<plo and phi<1 and 0<=qlo and qhi<1,'entire double-series tail domain')
 even=[iq(1)];qq=[iq(1)]
 for j in range(1,K+1):even.append(even[-1]*p*p/((2*j-1)*(2*j)))
 for k in range(1,K+1):qq.append(qq[-1]*q/k)
 v=iq(0)
 for j in range(K+1):
  for k in range(K+1):v+=even[j]*qq[k]/(2*j+2*k+1)
 pref=2*h*iv.exp(e);rem=pref*TAIL
 rlo,rhi=endpoints(rem);need(rlo>=0,'tail sign')
 return pref*v+enclosure(0,rhi),rem

def floor_old(s):
 if endpoints(s)==(Q(0),Q(0)):return delta
 need(endpoints(s)[0]>=0,'secondary inward')
 v=iq(0)
 for lo,hi,mass in bins:v+=mass*(1-iv.exp(-2*s*iv.log(iq(lo))))
 return delta*iv.sqrt(1+v/star)

def evaluate(L,U):
 x=iq(X) if L==C else wall(L,b)
 s=iq(0) if L==C else a*(cfun(x)-c0)
 entry,rem=entrant_integral(x,U);norm=floor_old(s)
 return {'L':L,'U':U,'x_left':x,'s':s,'old_norm_lower_expression':norm,'entry_integral_upper':entry,'retained_lower_expression':norm-entry,'entry_log_slope':-iq(1)/2+a*(iv.log(iq(U))/2-cfun(x)),'heat_support_gap':4*cfun(x)-iv.log(iq(U)),'entire_remainder':rem}
P=json.loads((F/'m774_PRIMARY_RESULT.json').read_text());S=json.loads((F/'m774_SECONDARY_RESULT.json').read_text())
# These broad exact weight cells are already outward enclosures. The second
# line need overlap the producer enclosures, not artificially fit inside them.
def compare(v,old,label):
 lo,hi=endpoints(v);ol,oh=Q(old['lo']),Q(old['hi'])
 need(lo<=oh and ol<=hi,'secondary inconsistent: '+label)
 for pre in ['FLOOR','CEIL','floor','ceil']:
  for k,w in old.items():
   if k.startswith(pre):
    d=int(k[len(pre):]);want=trunc(lo if pre.lower()=='floor' else hi,d,pre.lower()=='ceil')
    # Exact head decimal1/10 straddles one ULP on the old lines.
    if label.endswith('old_norm_lower_expression') and lo<=Q(1,10)<=hi:continue
    need(w==want,'secondary directed pair '+label+' '+k)

cache={};outrows=[];comparisons=0
for category in ['leaves','point_controls','rejected_parents']:
 for old in P[category]:
  key=(old['L'],old['U'])
  if key not in cache:cache[key]=evaluate(*key)
  z=cache[key];need(neg(z['entry_log_slope']),'density secondary');need(pos(z['heat_support_gap']),'heat secondary')
  for name,v in old.items():
   if isinstance(v,dict) and 'lo' in v:compare(z[name],v,category+str(key)+name);comparisons+=1
  if category!='rejected_parents':
   os=next(v for v in S[category] if (v['L'],v['U'])==key)
   for name,v in os.items():
    if name in z and isinstance(v,dict) and 'lo' in v:compare(z[name],v,'second '+category+str(key)+name);comparisons+=1
  if category=='leaves':need(pos(z['retained_lower_expression']-iq('1/100')),'second leaf fails')
  else:
   if category=='rejected_parents':need(neg(z['retained_lower_expression']-iq('1/100')),'second parent classification')
  outrows.append({'category':category,**{k:save(v) if k not in ['L','U'] else v for k,v in z.items()}})

anchors={'c_source':c0,'entry100000':100000*iv.exp(a*iv.log(iq(C))**2/4-(iq(1)/2+a*c0)*iv.log(iq(C))),'support_gap790988':4*c0-iv.log(iq(790988)),'source_left_gap':iq(X)-wall(C,a),'source_right_gap':wall(C+1,b)-X,'far_left_gap':iq(W)-wall(H,a),'far_right_gap':wall(H+1,b)-W}
for k,v in anchors.items():
 compare(v,P['anchors'][k],'anchor '+k);compare(v,S['anchors'][k],'second anchor '+k)
 if 'gap' in k:need(pos(v),'anchor gap')

old729=json.loads((F/'m729_primary_results.json').read_text())['intervals']
for key,name in [('TAIL_SEAM_LOWER_GAP','far_left_gap'),('TAIL_SEAM_UPPER_GAP','far_right_gap')]:
 lo,hi=old729[key];compare(anchors[name],{'lo':lo,'hi':hi},'direct729 '+key)
old767=json.loads((F/'m767_COMPOSITION_RESULT.json').read_text())['scalars']
for key,name in [('c','c_source'),('entry','entry100000'),('support_gap','support_gap790988'),('source_left_gap','source_left_gap'),('source_right_gap','source_right_gap')]:
 for mode in ['arb','rational_series']:
  lo,hi=old767[key][mode];compare(anchors[name],{'lo':lo,'hi':hi},'direct767 '+key+' '+mode)

# Exact closed real-index coverage, independently rederived from endpoints.
geometry=json.loads((F/'m774_GEOMETRY.json').read_text())
events={}
for L,U in geometry:
 need(C<=L<U<=H,'leaf exact interval')
 events[L]=events.get(L,0)+1;events[U]=events.get(U,0)-1
xs=sorted(events);active=0
for j,x in enumerate(xs[:-1]):
 active+=events[x];need(active==1,'open-index-cell coverage')
 need(xs[j+1]>x,'event order')
need(xs[0]==C and xs[-1]==H and active+events[H]==0,'cover ends')
# Independent integer census: half-open disjoint ownership except H is included.
counts=[U-L for L,U in geometry];owned=sum(counts)+1
need(owned==H-C+1,'integer target census')
entrants=sum(range(C+1,H+1)) # independent whole entrant list, not sampled mass
need(entrants==H*(H+1)//2-C*(C+1)//2,'complete entrant index sum')
need(sum(1 for _ in range(C+1,H+1))==H-C==1609011,'complete entrant count')
need(C<2**20<=H,'smooth entrant not optional')
# General wall identity is algebraic; these rational controls cover every leaf
# endpoint and both time endpoints without pretending a sample is the proof.
wall_controls=0
